function promAdaptativo(hist,sem,hasta){
  const YEARS=['2019','2020','2021','2022','2023','2024','2025'];
  const yrs=hasta?YEARS.filter(y=>parseInt(y)<=hasta):YEARS;
  const full=yrs.map(y=>hist[y]?.[sem]).filter(v=>v!=null).map(Number);
  if(!full.length)return null;
  const rec3=[];
  for(let i=yrs.length-1;i>=0&&rec3.length<3;i--){const v=hist[yrs[i]]?.[sem];if(v!=null)rec3.push(Number(v));}
  const rec2=rec3.slice(0,2);
  const pf=full.reduce((a,b)=>a+b,0)/full.length;
  const pr3=rec3.length>=2?rec3.reduce((a,b)=>a+b,0)/rec3.length:pf;
  const pr2=rec2.length===2?rec2.reduce((a,b)=>a+b,0)/2:pr3;
  const diff=pf>0?Math.abs(pf-pr3)/pf:0;
  const r1=diff>0.15;
  const r2=rec3.length===3&&rec3.every(v=>v>pf);
  const r3=rec3.length===3&&rec3.every(v=>v<pf);
  const r4=rec2.length===2&&rec2.every(v=>v<pf);
  const r5=rec2.length===2&&rec2.every(v=>v>pr3);
  if(r4||r5)return Math.round(pr2*10)/10;
  if(r1||r2||r3)return Math.round(pr3*10)/10;
  return Math.round(pf*10)/10;
}
function calcMeta(prom,cupo,pe,hayDem,acreditado){
  if(prom==null)return[null,'---'];
  const base=Math.min(prom,cupo);
  const pct=acreditado?0.05:0.10;
  const hd=hayDem!=null?hayDem:true;
  const dC=prom-cupo,dP=prom-pe;
  if(Math.abs(dC)<=2)return[Math.round(cupo*(1+pct)),'C1'];
  if(Math.abs(dP)<=2&&hd)return[Math.min(Math.round(pe*1.35),cupo),'C2'];
  if(dP<0&&hd)return[Math.round(pe*1.10),'C3'];
  if(dP<0&&!hd)return[Math.round(prom*1.10),'C4'];
  return[Math.round(base),'C5'];
}


const CM={
  C1:{c:'var(--c1)',p:'var(--c1p)',ico:'🎯',t:'Cerca del cupo máximo',txt:'Opera cerca del límite autorizado por el MEN.'},
  C2:{c:'var(--c2)',p:'var(--c2p)',ico:'📈',t:'Equilibrio + competencia activa',txt:'Cubre costos y el mercado privado lo respalda.'},
  C3:{c:'var(--c3)',p:'var(--c3p)',ico:'⚡',t:'Bajo PE + competencia activa',txt:'No cubre costos, pero el mercado existe. Meta aspiracional.'},
  C4:{c:'var(--c4)',p:'var(--c4p)',ico:'⚠️',t:'Bajo PE + UDES lidera',txt:'No cubre costos pero supera a la competencia privada.'},
  C5:{c:'var(--c5)',p:'var(--c5p)',ico:'📊',t:'Sostenible + UDES lidera',txt:'Programa sostenible. UDES capta más que sus competidores.'},
  '---':{c:'var(--g3)',p:'var(--g1)',ico:'—',t:'Sin dato',txt:'Sin promedio histórico para este semestre.'},
};

let sem='A';

function onCampus(){
  const c=document.getElementById('sc').value;
  const s=document.getElementById('sp');s.innerHTML='';
  ['Pregrado','Especialización','Maestría','Doctorado'].forEach(n=>{
    const g=D.filter(d=>d.campus===c&&d.nivel===n);if(!g.length)return;
    const og=document.createElement('optgroup');og.label=n+'s';
    g.forEach(d=>{const o=document.createElement('option');o.value=d.programa;o.textContent=d.programa;og.appendChild(o);});
    s.appendChild(og);
  });
  render();
}

function setSem(s){
  sem=s;
  document.getElementById('ba').className='sb'+(s==='A'?' on':'');
  document.getElementById('bb').className='sb'+(s==='B'?' on':'');
  render();
}

function toggleMarco(){
  document.getElementById('marr').classList.toggle('open');
  document.getElementById('mb').classList.toggle('open');
}

function render(){
  const c=document.getElementById('sc').value;
  const p=document.getElementById('sp').value;
  const hasta=parseInt(document.getElementById('sy').value);
  const d=D.find(x=>x.campus===c&&x.programa===p);
  if(!d){document.getElementById('out').innerHTML='';return;}

  const es2025=hasta===2025;
  const tag=document.getElementById('ytag');
  tag.className=es2025?'year-badge curr':'year-badge';
  tag.textContent=es2025?'Histórico completo':'Corte '+hasta;

  let pa,pb,meta,cond;
  if(es2025){
    pa=d.promA;pb=d.promB;
    meta=sem==='A'?d.metaA:d.metaB;
    cond=sem==='A'?d.condA:d.condB;
  } else {
    pa=promAdaptativo(d.hist,'A',hasta);
    pb=promAdaptativo(d.hist,'B',hasta);
    const hda=d.hayDemandaA,hdb=d.hayDemandaB;
    const [ma,ca]=calcMeta(pa,d.cupo,d.pe,hda,d.acreditado||false);
    const [mb,cb]=calcMeta(pb,d.cupo,d.pe,hdb,d.acreditado||false);
    if(sem==='A'){meta=ma;cond=ca;}else{meta=mb;cond=cb;}
  }

  const prom=sem==='A'?pa:pb;
  const compV=sem==='A'?d.prom_comp_A:d.prom_comp_B;
  const nIes=d.n_ies||0;
  const hayDem=sem==='A'?d.hayDemandaA:d.hayDemandaB;
  const C=CM[cond]||CM['---'];

  const total=(prom||0)+(compV||0);
  const pctU=total>0?Math.round((prom||0)/total*100):null;
  const pctC=pctU!=null?100-pctU:null;
  const promIes=(compV&&nIes>0)?Math.round(compV/nIes):null;

  const dCupo=prom!=null?+(prom-d.cupo).toFixed(1):null;
  const dPE=prom!=null?+(prom-d.pe).toFixed(1):null;
  const sg=v=>v==null?'—':(v>=0?'▲ ':'▼ ')+Math.abs(v).toFixed(1);

  const YEARS=['2019','2020','2021','2022','2023','2024','2025'];
  const yrsC=YEARS.filter(y=>parseInt(y)<=hasta);
  const allV=yrsC.map(y=>d.hist[y]?.[sem]).filter(v=>v!=null).map(Number);
  const maxV=Math.max(...allV,d.pe,meta||0,1);

  const bars=yrsC.map(y=>{
    const v=d.hist[y]?.[sem];
    const h=v!=null?Math.max(Math.round((Number(v)/maxV)*84),2):0;
    const clr=v!=null?C.c:'var(--g1)';
    return `<div class="bc">
      <span class="bv" style="color:${v!=null?C.c:'var(--g2)'}">${v!=null?v:''}</span>
      <div class="br" style="height:${h}px;background:${clr}"></div>
      <span class="byr" style="color:${parseInt(y)===hasta?C.c:'var(--g3)'}">${y}</span>
    </div>`;
  }).join('');
  const peH=Math.round((d.pe/maxV)*84);
  const peBar=`<div class="bc"><span class="bv" style="color:var(--go)">${d.pe}</span><div class="br bpe" style="height:${peH}px"></div><span class="byr" style="color:var(--go)">PE</span></div>`;

  const alerta=meta!=null&&meta>d.cupo?`<div style="margin-top:10px;font-size:12px;background:#FEF3E2;border-left:3px solid var(--go);padding:8px 12px;border-radius:0 6px 6px 0;color:#7A4A00">⚠ Meta (${meta}) supera cupo MEN (${d.cupo}). Verificar con Vicerrectoría.</div>`:'';

  const condTxt=d.cupoAnual?'Cupo fijo anual por resolución MEN.':C.txt;
  const condTitle=d.cupoAnual?'📌 Cupo fijo anual (MEN)':cond+' · '+C.t;

  // Bloque mercado
  let mktHTML='';
  if(compV!=null){
    const demChip=hayDem
      ?`<span class="dem-chip" style="background:#E6F4EC;color:var(--c2)">✓ Hay demanda &nbsp;·&nbsp; ${nIes} IES privada${nIes>1?'s':''} en el municipio</span>`
      :`<span class="dem-chip" style="background:var(--azpp);color:var(--az)">↑ UDES lidera el segmento privado</span>`;
    mktHTML=`<div class="mkt-card">
      <div class="mkt-title">Análisis de mercado · IES privadas · sem. ${sem}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
        <div style="background:var(--azpp);border-radius:8px;padding:12px 14px">
          <div style="font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--g3);margin-bottom:4px">UDES · prom. histórico</div>
          <div style="font-family:'Barlow Condensed',sans-serif;font-size:32px;font-weight:800;color:var(--az);line-height:1">${prom!=null?prom:'—'}</div>
          <div style="font-size:11px;color:var(--g3);margin-top:2px">est. · participación: ${pctU!=null?pctU+'%':'—'}</div>
        </div>
        <div style="background:var(--g0);border-radius:8px;padding:12px 14px">
          <div style="font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--g3);margin-bottom:4px">Competencia privada${nIes>0?' · '+nIes+' IES':''}</div>
          <div style="font-family:'Barlow Condensed',sans-serif;font-size:32px;font-weight:800;color:var(--g4);line-height:1">${compV!=null?Math.round(compV):'—'}</div>
          <div style="font-size:11px;color:var(--g3);margin-top:2px">${promIes?'total · '+promIes+' est. por IES':'total matriculados'}</div>
        </div>
      </div>
      ${demChip}
    </div>`;
  } else {
    mktHTML=`<div class="mkt-card"><div class="mkt-title">Participación de mercado</div><span class="dem-chip" style="background:var(--g1);color:var(--g3)">Sin dato de competencia privada</span></div>`;
  }

  const barInd=prom!=null&&compV!=null
    ?`<div class="ind-bar"><div class="ind-fill-udes" style="width:${pctU||0}%;background:var(--az)"></div><div class="ind-fill-comp" style="width:${pctC||0}%"></div></div>`
    :`<div class="ind-bar"><div class="ind-fill-udes" style="width:${Math.min(Math.round((prom||0)/d.cupo*100),100)}%;background:var(--az)"></div></div>`;

  document.getElementById('out').innerHTML=`
<div class="hero">
  <div class="hero-head">
    <div class="hero-prog">${d.programa}</div>
    <div class="hero-pills">
      <span class="pill">${c}</span><span class="pill">${d.nivel}</span>
      <span class="pill">Cupo MEN: <b style="color:#fff">${d.cupo}</b></span>
      <span class="pill">PE: <b style="color:#fff">${d.pe} est.</b></span>
      ${d.acreditado?'<span class="pill pill-ac">★ Acreditado</span>':''}
      ${!es2025?`<span class="pill" style="background:rgba(196,154,34,.3);color:#FFD966">Corte ${hasta}</span>`:''}
    </div>
  </div>
  <div class="hero-body" style="border-top-color:${C.c}">
    <div class="meta-blk">
      <div class="meta-lbl">Meta · Sem. ${sem}${!es2025?' · Corte '+hasta:''}</div>
      ${meta!=null?`<div class="meta-n" style="color:${C.c}">${meta}</div><div class="meta-unit">matriculados primer curso</div>`:`<div style="font-family:'Barlow Condensed',sans-serif;font-size:40px;color:var(--g3)">—</div>`}
      <div class="cond-banner" style="background:${C.p}">
        <span class="cond-icon">${d.cupoAnual?'📌':C.ico}</span>
        <div><div class="cond-title" style="color:${C.c}">${condTitle}</div><div class="cond-txt">${condTxt}</div></div>
      </div>${alerta}
    </div>
    <div class="ind-blk">
      <div class="ind-row">
        <span class="ind-label">Promedio histórico${!es2025?' (hasta '+hasta+')':''}</span>
        <span class="ind-val" style="color:var(--az)">${prom!=null?prom:'—'}</span>
        <span class="ind-sub">sem. ${sem} · hasta ${hasta}</span>
        ${barInd}
      </div>
      <div class="ind-row">
        <span class="ind-label">Meta propuesta</span>
        <span class="ind-val" style="color:${C.c}">${meta!=null?meta:'—'}</span>
        <span class="ind-sub">${dCupo!=null?sg(dCupo)+' vs cupo':''} ${dPE!=null?'· '+sg(dPE)+' vs PE':''}</span>
        <div class="ind-bar"><div class="ind-fill-udes" style="width:${Math.min(Math.round((meta||0)/d.cupo*100),100)}%;background:${C.c}"></div></div>
      </div>
    </div>
  </div>
</div>
${mktHTML}
<div class="hist">
  <div class="sec-lbl">Histórico matriculados · Sem. ${sem}${!es2025?' · hasta '+hasta:''}</div>
  <div class="bars">${bars}${peBar}</div>
  <div class="hist-line"></div>
  <div class="hist-leg">
    <span><div class="leg-dot" style="background:${C.c}"></div>Matriculados UDES</span>
    <span><div class="leg-pe"></div>PE = ${d.pe}</span>
    ${meta!=null?`<span><div class="leg-dot" style="background:${C.c};opacity:.4"></div>Meta: ${meta}</span>`:''}
  </div>
</div>`;
}



// Init
const camps=[...new Set(D.map(d=>d.campus))];
const sc=document.getElementById('sc');
camps.forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;sc.appendChild(o);});
onCampus();


